   7 export async function getUserProfile(id: string): Promise<UserProfile | null> {
   8     if (!id) return null;
   9     const userDoc = await adminDb.collection('users').doc(id).get();
  10     if (!userDoc.exists) {
  11         return null;
  12     }
  13     const data = userDoc.data();
  14     return { id: userDoc.id, ...data } as UserProfile;
  15 }
