  17 export async function getPaginatedUsers({ limit, lastVisibleId }: { limit: number, lastVisibleId?: string }) {
  18     let query = adminDb.collection('users')
  19         .orderBy('createdAt', 'desc')
  20         .limit(limit + 1); // Fetch one extra to check for hasNextPage
  21 
  22     if (lastVisibleId) {
  23         const lastDoc = await adminDb.collection('users').doc(lastVisibleId).get();
  24         if (lastDoc.exists) {
  25             query = query.startAfter(lastDoc);
  26         }
  27     }
  28 
  29     const snapshot = await query.get();
  30     const users = snapshot.docs.slice(0, limit).map(doc => ({ id: doc.id, ...doc.data() })) as UserProfile[];
  31     const hasNextPage = snapshot.docs.length > limit;
  32     const newLastVisibleId = hasNextPage ? snapshot.docs[snapshot.docs.length - 2].id : null;
  33 
  34     return { users, hasNextPage, lastVisibleId: newLastVisibleId };
  35 }
  36 
  37 export async function createUser(data: Omit<UserProfile, 'id' | 'createdAt' | 'updatedAt'> & { password?: string }): Promise<{ user: { uid: string, email?: string | undefined } }> {
  38     const { email, password, name, role, credits } = data;
  39 
  40     const userRecord = await adminAuth.createUser({ email, password, displayName: name });
  41 
  42     const newUserProfile: Omit<UserProfile, 'id'> = {
  43         name,
  44         email,
  45         credits: credits,
  46         role: role,
  47         createdAt: new Date().toISOString(),
  48         updatedAt: new Date().toISOString(),
  49         bio: '',
  50         profilePictureUrl: '',
  51         hasCompletedOnboarding: false,
  52         lastDailyCreditUpdate: new Date(0).toISOString(), // Set to epoch to ensure eligibility
  53     };
  54 
  55     await adminDb.collection('users').doc(userRecord.uid).set(newUserProfile);
  56 
  57     return { user: { uid: userRecord.uid, email: userRecord.email } };
  58 }
  59 
  60 export async function updateUser(userId: string, data: Partial<UserProfile>): Promise<UserProfile> {
  61     const updatePayload = {
  62         ...data,
  63         updatedAt: new Date().toISOString(),
  64     };
  65     await adminDb.collection('users').doc(userId).update(updatePayload);
  66     const updatedUser = await getUserProfile(userId);
  67     if (!updatedUser) throw new Error("Failed to refetch updated user profile.");
  68     return updatedUser;
  69 }
  70 
  71 export async function deleteUser(userId: string) {
  72     await adminAuth.deleteUser(userId);
  73     await adminDb.collection('users').doc(userId).delete();
  74 }
  75 
  76 export async function resetUserPassword(userId: string, newPassword: string): Promise<void> {
  77     await adminAuth.updateUser(userId, { password: newPassword });
  78 }
  79 
  80 export async function deductUserCredits(userId: string, creditsToDeduct: number): Promise<number> {
  81     const userRef = adminDb.collection('users').doc(userId);
  82 
  83     return await adminDb.runTransaction(async (transaction) => {
  84         const userDoc = await transaction.get(userRef);
  85         if (!userDoc.exists) {
  86             throw new Error("User not found");
  87         }
  88 
  89         const userData = userDoc.data() as UserProfile;
  90         let currentCredits = userData.credits ?? 0;
  91         const lastUpdate = userData.lastDailyCreditUpdate ? new Date(userData.lastDailyCreditUpdate).getTime() : 0;
  92         const twentyFourHours = 24 * 60 * 60 * 1000;
  93 
  94         const updates: { [key: string]: any } = {};
  95 
  96         // Check if it's time for a daily credit refresh
  97         if (Date.now() - lastUpdate > twentyFourHours) {
  98             if (currentCredits < 10) {
  99                 currentCredits = 10;
 100                 updates.credits = currentCredits;
 101             }
 102             updates.lastDailyCreditUpdate = new Date().toISOString();
 103         }
 104 
 105         if (currentCredits < creditsToDeduct) {
 106             throw { status: 402, message: "Insufficient credits. Please purchase more credits to continue." };
 107         }
 108 
 109         const newBalance = currentCredits - creditsToDeduct;
 110         updates.credits = newBalance;
 111         updates.updatedAt = new Date().toISOString();
 112 
 113         transaction.update(userRef, updates);
 114 
 115         return newBalance;
 116     });
 117 }
 118 
 119 export async function addUserCredits(userId: string, creditsToAdd: number): Promise<void> {
 120     const userRef = adminDb.collection('users').doc(userId);
 121     await userRef.update({
 122         credits: FieldValue.increment(creditsToAdd),
 123         updatedAt: new Date().toISOString(),
 124     });
 125 }
