  50 /**
  51  * Mutation hook for creating a new user.
  52  * Requires admin privileges.
  53  */
  54 export function useCreateUser(options?: { onSuccess?: (data: any) => void }) {
  55   const queryClient = useQueryClient();
  56   const { firebaseUser } = useAuth();
  57   return useMutation({
  58     mutationFn: async (data: any) => {
  59       const token = await getAuthenticatedToken(firebaseUser);
  60       return createUserService(data, token);
  61     },
  62     onSuccess: (data) => {
  63       queryClient.invalidateQueries({ queryKey: userKeys.lists() });
  64       options?.onSuccess?.(data);
