  30     email: z.string().email('Invalid email address').optional(),
  31     bio: z.string().optional(),
  32     credits: z.coerce.number().int().min(0).optional(),
  33     role: z.enum(['user', 'admin']).optional(),
  34     hasCompletedOnboarding: z.boolean().optional(),
  35     apiKeys: z.record(z.string()).optional(),
  36 });
  37 
  38 const userUpdateSchema = z.object({
  39     name: z.string().min(1, 'Name is required').optional(),
  40     email: z.string().email('Invalid email address').optional(),
  41     bio: z.string().optional(),
  42     hasCompletedOnboarding: z.boolean().optional(),
  43     apiKeys: z.record(z.string()).optional(),
  44 });
  45 
