  47 // PUT (update) a user profile
  48 export const PUT = withAuth(async ({ request, params, user: requester }) => {
  49     try {
  50         const {id:userId} = await params;
  51         const body = await request.json();
  52         let validation;
  53 
  54         // An admin can update any field. A regular user can only update their own profile.
  55         if (requester.role !== 'admin') {
  56             if (userId !== requester.id) {
  57                 return handleApiError({ message: "Forbidden: Users can only update their own profile." }, 403);
  58             }
  59             validation = userUpdateSchema.safeParse(body);
  60         } else {
  61             validation = adminUpdateUserSchema.safeParse(body);
  62         }
  63 
  64         if (!validation.success) {
  65             return handleApiError(validation.error);
  66         }
  67 
  68         const updateData: any = { ...validation.data, updatedAt: new Date().toISOString() };
  69 
  70         // If email is being updated, update it in Firebase Auth as well
  71         if (validation.data.email && validation.data.email !== requester.email) {
  72             await adminAuth.updateUser(userId, { email: validation.data.email });
  73         }
  74 
  75         await adminDb.collection("users").doc(userId).update(updateData);
  76 
  77         revalidatePath(`/profile/${userId}`);
  78         revalidatePath('/admin/manage-users');
  79 
  80         const updatedUser = await getUserProfile(userId);
  81         return createApiResponse(updatedUser, 200);
  82     } catch (error: any) {
  83         if (error.code === 'auth/email-already-exists') {
  84             return handleApiError({ message: "This email is already in use by another account." }, 409);
  85         }
  86         return handleApiError(error);
  87     }
  88 });
